def f(arr, n, k, c):
	ans = 0
	i = 0
	while arr[i] == c and i < n:
		ans += 1
		i += 1
	if i >= n:
		return n
	j = n - 1
	while arr[j] == c:
		ans += 1
		j -= 1
	if k == 0 and ans != n:
		return -1
	if k == 1:
		return ans
	h = []
	heapq.heapify(h)
	index = i
	temp = 0
	for m in range(i, j + 1):
		if arr[m] == c:
			temp += 1
		else:
			if temp > 0:
				heapq.heappush(h, -1 * temp)
			temp = 0
	while k > 1 and len(h) > 0:
		ans += -1 * heapq.heappop(h)
		k -= 1
	if ans == 0:
		return -1
	else:
		return ans
