import math

def divisors(n):
	if n < 2:
		return []
	r = [n]
	nn = int(math.floor(math.sqrt(n)))
	if nn * nn == n:
		r.append(nn)
		nn -= 1
	for i in range(2, nn + 1):
		if n % i == 0:
			r.append(i)
			r.append(n // i)
	r.sort(reverse=True)
	return r
