def moveCoin(x, y):
	if x > 1:
		if y > 0:
			yield (x - 2, y - 1)
		if y < 14:
			yield (x - 2, y + 1)
	if y > 1:
		if x > 0:
			yield (x - 1, y - 2)
		if x < 14:
			yield (x + 1, y - 2)

def getGrundy(x, y):
	if grundy[x][y] != -1:
		return grundy[x][y]
	s = set()
	for (i, j) in moveCoin(x, y):
		s.add(getGrundy(i, j))
	mex = 0
	while mex in s:
		mex += 1
	grundy[x][y] = mex
	return mex
