			result[i * j][result[i * j][0]] = i
	return result

def getMultipliers(n):
	result = [[1] for i in range(n + 1)]
	for i in range(2, n + 1):
		limit = n // i
		for j in range(1, limit + 1):
			result[i * j].append(i)
	return result

def getToupleCount(n):
	gc.disable()
	multiplies = getMultipliers(n)
	gc.enable()
	result = n - 2
	for a in range(2, n // 2 + 1):
		limit = n // a
		elems = set()
		for x in range(1, n // a):
			for d in multiplies[n - a * x]:
				if d > a:
					elems.add(d)
		result += len(elems)
	return result
