			if dis < cell[i][3] + cell[j][3]:
				uf.union(i, j)
			else:
				edge.append((dis - (cell[i][3] + cell[j][3]), i, j))
	edge.sort()
	ans = 0
	num = n
	for (c, a, b) in edge:
		if not uf.same(a, b):
			uf.union(a, b)
